dynamic-array.pseudocode:
class DynamicArray:
    def __init__(self):
        self.cap, self.size = 1, 0
        self.data = [None] * self.cap

    def append(self, x):
        if self.size == self.cap:  # 가득 참 → 2배 확장
            self._resize(2 * self.cap)
        self.data[self.size] = x
        self.size += 1

    def _resize(self, new_cap):
        new = [None] * new_cap
        for i in range(self.size):  # O(n) 복사
            new[i] = self.data[i]
        self.data, self.cap = new, new_cap

    def get(self, i):
        if not 0 <= i < self.size:
            raise IndexError(i)
        return self.data[i]  # 임의 접근 O(1)

dynamic-pricing.pseudocode:
def demand_ce(p, q0, p0, e):
    # 일정 탄력성 수요 모델 (e < 0: 가격 탄력성)
    return q0 * (p / p0) ** e

def best_price(candidates, demand, stock, cost):
    # demand(p): 가격 p에서의 예측 수요량
    best_p, best_profit = None, float('-inf')
    for p in candidates:
        q = min(demand(p), stock)  # 재고 한도 내 판매
        profit = (p - cost) * q
        if profit > best_profit:
            best_p, best_profit = p, profit
    return best_p

# 주기적으로 수요 재추정 → best_price 재계산 → 가격 반영

dynamic-scaling.pseudocode:
def target_tracking(cur_n, metric, target, lo, hi):
    # 지표가 목표값이 되도록 인스턴스 수 비례 조정
    n = ceil(cur_n * metric / target)
    return max(lo, min(hi, n))  # 최소·최대 범위 제한

def step_delta(metric, steps):
    # steps: [(하한, 상한, 증감 수), ...] 단계별 정책
    for low, high, delta in steps:
        if low <= metric < high:
            return delta
    return 0

def scaling_loop(g, target, cooldown):
    while True:
        m = g.avg_metric()  # 예: 평균 CPU %
        n = target_tracking(g.size, m, target, g.lo, g.hi)
        if n != g.size:
            g.resize(n)
            sleep(cooldown)  # 연속 조정 방지
        sleep(60)

dynamic-voltage-and-frequency-scaling.pseudocode:
def ondemand(cpu, levels, up_threshold=80):
    # levels: 주파수 오름차순 [(freq, volt), ...] P-state
    load = cpu.utilization()  # 최근 샘플 구간 사용률 %
    f_max = levels[-1][0]
    if load > up_threshold:
        target = len(levels) - 1  # 즉시 최고 주파수
    else:
        need = f_max * load / 100  # 부하 비례 (단순화)
        target = 0
        while levels[target][0] < need:
            target += 1
    set_pstate(cpu, levels[target])

def set_pstate(cpu, level):
    freq, volt = level
    if freq > cpu.freq:
        cpu.set_voltage(volt)  # 상향: 전압 먼저 올림
        cpu.set_freq(freq)
    else:
        cpu.set_freq(freq)  # 하향: 주파수 먼저 내림
        cpu.set_voltage(volt)
